def f(s):
    """
    Returns the string `s` in the format "QX YYYY",
    where QX is the quarter number (1 for Q1, 2 for Q2, etc.)
    and YYYY is the year.
    """
    if len(s) != 10:
        raise ValueError("Input string must be in 'YYYY-MM-DD' format.")
    year, month = map(int, s.split('-'))
    if month in [1, 2, 3]:
        return 'Q1 %d' % year
    elif month in [4, 5, 6]:
        return 'Q2 %d' % year
    elif month in [7, 8, 9]:
        return 'Q3 %d' % year
    elif month in [10, 11, 12]:
        return 'Q4 %d' % year
    else:
        raise ValueError('Invalid month number in input string.')

